#!/usr/bin/env Rscript

############################################################
## run_01_prepare_baypass_results.R
##
## Cactoblastis cactorum
## Final BayPass results preparation and convergence
##
## INPUT:
##   Three independent BayPass v3.1 runs of the all-SNP
##   dataset generated by run_00.
##
## SEEDS:
##   12345
##   67890
##   13579
##
## FINAL ANALYSES:
##
##   Convergence:
##     1. Förstner-Moonen distance between Omega matrices
##        using BayPass fmd.dist()
##     2. Stability of posterior Beta-prior parameters
##     3. Pairwise Spearman correlations of XtX
##     4. Pairwise Spearman correlations of C2
##     5. Pairwise Spearman correlations of covariate BFs
##
##   Final statistics:
##     XtX = representative converged seed 12345
##     C2  = representative converged seed 12345
##     GEA = median BF(dB) across the three seeds
##
## FINAL GEA COVARIATES:
##     TempPC1
##     PrecipPC1
##     AridityIndex
##     Elevation
##     Latitude
##     Longitude
############################################################


suppressPackageStartupMessages({
    library(data.table)
})


############################################################
## 0. SETTINGS
############################################################

BASE <- "/home/dpoveda/micetral/Population_snps/baypass"

RUNBASE <- file.path(
    BASE,
    "runs_10x",
    "all_snps"
)

METAFILE <- paste0(
    "/home/dpoveda/micetral/Population_snps/",
    "baypass_preparation/metadata/",
    "all_snps.baypass.snp_metadata.tsv"
)

OUTBASE <- file.path(
    BASE,
    "selection_scan",
    "prepared_statistics",
    "all_snps"
)

CONV_OUT <- file.path(
    OUTBASE,
    "convergence"
)

dir.create(
    OUTBASE,
    recursive = TRUE,
    showWarnings = FALSE
)

dir.create(
    CONV_OUT,
    recursive = TRUE,
    showWarnings = FALSE
)


SEEDS <- c(
    "12345",
    "67890",
    "13579"
)

REP_SEED <- "12345"


############################################################
## 1. FINAL COVARIATES USED IN THE MANUSCRIPT
############################################################

COV_MAP <- data.table(
    COVARIABLE = 1:6,
    Covariate = c(
        "TempPC1",
        "PrecipPC1",
        "AridityIndex",
        "Elevation",
        "Latitude",
        "Longitude"
    )
)


############################################################
## 2. BAYPASS R UTILITY
##
## fmd.dist() is used for the Förstner-Moonen distance
## between independently estimated Omega matrices.
############################################################

BAYPASS_UTILS <- paste0(
    "/home/dpoveda/micetral/selection/baypass/",
    "baypass_public/utils/baypass_utils.R"
)

if (!file.exists(BAYPASS_UTILS)) {
    stop(
        "BayPass utility file not found:\n",
        BAYPASS_UTILS
    )
}

source(BAYPASS_UTILS)

if (!exists("fmd.dist")) {
    stop(
        "BayPass function fmd.dist() was not loaded."
    )
}

message(
    "Loaded BayPass fmd.dist() from:\n",
    BAYPASS_UTILS
)


############################################################
## 3. HELPER FUNCTIONS
############################################################

get_prefix <- function(seed) {

    file.path(
        RUNBASE,
        paste0("seed_", seed),
        paste0(
            "BP_all_snps_seed",
            seed
        )
    )
}


read_metadata <- function() {

    if (!file.exists(METAFILE)) {
        stop(
            "Metadata file not found:\n",
            METAFILE
        )
    }

    x <- fread(
        METAFILE,
        showProgress = FALSE
    )

    required <- c(
        "BayPass_row",
        "CHROM",
        "SNP",
        "POS",
        "REF",
        "ALT"
    )

    if (!all(required %in% names(x))) {
        stop(
            "Metadata missing required columns."
        )
    }

    x[, BayPass_row := as.integer(BayPass_row)]
    x[, POS := as.integer(POS)]

    if (anyDuplicated(x$BayPass_row)) {
        stop(
            "Duplicated BayPass_row values in metadata."
        )
    }

    x
}


read_omega <- function(seed) {

    file <- paste0(
        get_prefix(seed),
        "_mat_omega.out"
    )

    if (!file.exists(file)) {
        stop(
            "Missing Omega file:\n",
            file
        )
    }

    x <- as.matrix(
        read.table(
            file,
            header = FALSE,
            check.names = FALSE
        )
    )

    storage.mode(x) <- "numeric"

    if (nrow(x) != ncol(x)) {
        stop(
            "Omega matrix is not square:\n",
            file
        )
    }

    x
}


read_beta_prior <- function(seed) {

    file <- paste0(
        get_prefix(seed),
        "_summary_beta_params.out"
    )

    if (!file.exists(file)) {
        stop(
            "Missing Beta-prior file:\n",
            file
        )
    }

    x <- fread(
        file,
        showProgress = FALSE
    )

    if (!all(c("PARAM", "Mean") %in% names(x))) {
        stop(
            "Unexpected Beta-prior columns:\n",
            file
        )
    }

    alpha <- x[
        PARAM == "a_beta_pi",
        Mean
    ]

    beta <- x[
        PARAM == "b_beta_pi",
        Mean
    ]

    if (length(alpha) != 1 ||
        length(beta) != 1) {

        stop(
            "Could not identify unique a_beta_pi/b_beta_pi."
        )
    }

    data.table(
        Seed = seed,
        alpha_mean = as.numeric(alpha),
        beta_mean = as.numeric(beta)
    )
}


read_xtx <- function(seed) {

    file <- paste0(
        get_prefix(seed),
        "_summary_pi_xtx.out"
    )

    if (!file.exists(file)) {
        stop(
            "Missing XtX file:\n",
            file
        )
    }

    x <- fread(
        file,
        showProgress = FALSE
    )

    required <- c(
        "MRK",
        "M_P",
        "SD_P",
        "M_XtX",
        "SD_XtX",
        "XtXst",
        "log10(1/pval)"
    )

    if (!all(required %in% names(x))) {
        stop(
            "XtX file missing required columns:\n",
            file
        )
    }

    x[, MRK := as.integer(MRK)]

    x
}


read_c2 <- function(seed) {

    file <- paste0(
        get_prefix(seed),
        "_summary_contrast.out"
    )

    if (!file.exists(file)) {
        stop(
            "Missing C2 file:\n",
            file
        )
    }

    x <- fread(
        file,
        showProgress = FALSE
    )

    required <- c(
        "CONTRAST",
        "MRK",
        "C2",
        "log10(1/pval)"
    )

    if (!all(required %in% names(x))) {
        stop(
            "C2 file missing required columns:\n",
            file
        )
    }

    x[, CONTRAST := as.integer(CONTRAST)]
    x[, MRK := as.integer(MRK)]

    if (length(unique(x$CONTRAST)) != 1) {
        stop(
            "Expected a single C2 host contrast."
        )
    }

    x
}


read_bf <- function(seed) {

    file <- paste0(
        get_prefix(seed),
        "_summary_betai_reg.out"
    )

    if (!file.exists(file)) {
        stop(
            "Missing GEA BF file:\n",
            file
        )
    }

    x <- fread(
        file,
        showProgress = FALSE
    )

    required <- c(
        "COVARIABLE",
        "MRK",
        "BF(dB)"
    )

    if (!all(required %in% names(x))) {
        stop(
            "BF file missing required columns:\n",
            file
        )
    }

    x[, COVARIABLE := as.integer(COVARIABLE)]
    x[, MRK := as.integer(MRK)]

    ## Retain only the six covariates used in the manuscript
    x <- x[
        COVARIABLE %in% COV_MAP$COVARIABLE
    ]

    x[
        ,
        .(
            MRK,
            COVARIABLE,
            BFdb = as.numeric(`BF(dB)`)
        )
    ]
}


pairwise_correlations <- function(
    values,
    value_column,
    statistic
) {

    pairs <- combn(
        SEEDS,
        2,
        simplify = FALSE
    )

    result <- lapply(
        pairs,
        function(pair) {

            s1 <- pair[1]
            s2 <- pair[2]

            x <- values[[s1]][
                ,
                .(
                    MRK,
                    value1 = get(value_column)
                )
            ]

            y <- values[[s2]][
                ,
                .(
                    MRK,
                    value2 = get(value_column)
                )
            ]

            z <- merge(
                x,
                y,
                by = "MRK"
            )

            data.table(
                Statistic = statistic,
                Seed1 = s1,
                Seed2 = s2,
                N_SNPs = nrow(z),
                Spearman_rho = cor(
                    z$value1,
                    z$value2,
                    method = "spearman",
                    use = "complete.obs"
                ),
                Pearson_r = cor(
                    z$value1,
                    z$value2,
                    method = "pearson",
                    use = "complete.obs"
                )
            )
        }
    )

    rbindlist(result)
}


############################################################
## 4. READ SNP METADATA
############################################################

META <- read_metadata()

message(
    "Metadata SNPs: ",
    nrow(META)
)


############################################################
## 5. READ ALL THREE BAYPASS RUNS
############################################################

OMEGA <- list()
BETA <- list()
XTX <- list()
C2 <- list()
BF <- list()

for (seed in SEEDS) {

    message(
        "Reading BayPass seed ",
        seed,
        " ..."
    )

    OMEGA[[seed]] <- read_omega(seed)

    BETA[[seed]] <- read_beta_prior(seed)

    XTX[[seed]] <- read_xtx(seed)

    C2[[seed]] <- read_c2(seed)

    BF[[seed]] <- read_bf(seed)
}


############################################################
## 6. CONVERGENCE: OMEGA
##    Förstner-Moonen distance using BayPass fmd.dist()
############################################################

seed_pairs <- combn(
    SEEDS,
    2,
    simplify = FALSE
)

OMEGA_FMD <- rbindlist(
    lapply(
        seed_pairs,
        function(pair) {

            s1 <- pair[1]
            s2 <- pair[2]

            if (!all(
                dim(OMEGA[[s1]]) ==
                dim(OMEGA[[s2]])
            )) {
                stop(
                    "Omega dimensions differ between seeds ",
                    s1,
                    " and ",
                    s2
                )
            }

            data.table(
                Seed1 = s1,
                Seed2 = s2,
                FMD = as.numeric(
                    fmd.dist(
                        OMEGA[[s1]],
                        OMEGA[[s2]]
                    )
                )
            )
        }
    )
)

fwrite(
    OMEGA_FMD,
    file.path(
        CONV_OUT,
        "Omega_FMD_between_seeds.tsv"
    ),
    sep = "\t"
)


############################################################
## 7. CONVERGENCE: BETA-PRIOR PARAMETERS
############################################################

BETA_TABLE <- rbindlist(
    BETA,
    use.names = TRUE
)

fwrite(
    BETA_TABLE,
    file.path(
        CONV_OUT,
        "Beta_prior_parameters_by_seed.tsv"
    ),
    sep = "\t"
)


############################################################
## 8. CONVERGENCE: XTX
############################################################

XTX_COR <- pairwise_correlations(
    XTX,
    value_column = "M_XtX",
    statistic = "XtX"
)

fwrite(
    XTX_COR,
    file.path(
        CONV_OUT,
        "XtX_seed_correlations.tsv"
    ),
    sep = "\t"
)


############################################################
## 9. CONVERGENCE: C2
############################################################

C2_COR <- pairwise_correlations(
    C2,
    value_column = "C2",
    statistic = "C2"
)

fwrite(
    C2_COR,
    file.path(
        CONV_OUT,
        "C2_seed_correlations.tsv"
    ),
    sep = "\t"
)


############################################################
## 10. MERGE GEA BFs ACROSS THREE SEEDS
############################################################

BF_SEEDS <- list()

for (seed in SEEDS) {

    x <- copy(
        BF[[seed]]
    )

    setnames(
        x,
        "BFdb",
        paste0(
            "BF_seed",
            seed
        )
    )

    BF_SEEDS[[seed]] <- x
}


BF_MERGED <- Reduce(
    function(x, y) {

        merge(
            x,
            y,
            by = c(
                "MRK",
                "COVARIABLE"
            ),
            all = TRUE,
            sort = FALSE
        )
    },
    BF_SEEDS
)


bf_columns <- paste0(
    "BF_seed",
    SEEDS
)

if (
    anyNA(
        BF_MERGED[
            ,
            ..bf_columns
        ]
    )
) {
    stop(
        "Missing BF values after merging seeds."
    )
}


############################################################
## 11. CONVERGENCE: COVARIATE-SPECIFIC BF
############################################################

BF_COR_RESULTS <- list()

counter <- 1

for (cov in COV_MAP$COVARIABLE) {

    cov_name <- COV_MAP[
        COVARIABLE == cov,
        Covariate
    ]

    x <- BF_MERGED[
        COVARIABLE == cov
    ]

    for (pair in seed_pairs) {

        s1 <- pair[1]
        s2 <- pair[2]

        col1 <- paste0(
            "BF_seed",
            s1
        )

        col2 <- paste0(
            "BF_seed",
            s2
        )

        BF_COR_RESULTS[[counter]] <- data.table(
            COVARIABLE = cov,
            Covariate = cov_name,
            Seed1 = s1,
            Seed2 = s2,
            N_SNPs = nrow(x),
            Spearman_rho = cor(
                x[[col1]],
                x[[col2]],
                method = "spearman",
                use = "complete.obs"
            ),
            Pearson_r = cor(
                x[[col1]],
                x[[col2]],
                method = "pearson",
                use = "complete.obs"
            )
        )

        counter <- counter + 1
    }
}


BF_COR <- rbindlist(
    BF_COR_RESULTS
)

setorder(
    BF_COR,
    COVARIABLE,
    Seed1,
    Seed2
)

fwrite(
    BF_COR,
    file.path(
        CONV_OUT,
        "GEA_BF_seed_correlations.tsv"
    ),
    sep = "\t"
)


BF_COR_SUMMARY <- BF_COR[
    ,
    .(
        Mean_Spearman = mean(
            Spearman_rho
        ),
        Median_Spearman = median(
            Spearman_rho
        ),
        Min_Spearman = min(
            Spearman_rho
        ),
        Max_Spearman = max(
            Spearman_rho
        ),
        Mean_Pearson = mean(
            Pearson_r
        )
    ),
    by = .(
        COVARIABLE,
        Covariate
    )
]

fwrite(
    BF_COR_SUMMARY,
    file.path(
        CONV_OUT,
        "GEA_BF_seed_correlations_summary.tsv"
    ),
    sep = "\t"
)


############################################################
## 12. FINAL GEA STATISTIC
##
## Median BF(dB) across the three converged MCMC runs,
## as reported in the manuscript.
############################################################

BF_MERGED[
    ,
    BF_median := apply(
        .SD,
        1,
        median
    ),
    .SDcols = bf_columns
]

BF_MERGED[
    ,
    BF_min := apply(
        .SD,
        1,
        min
    ),
    .SDcols = bf_columns
]

BF_MERGED[
    ,
    BF_max := apply(
        .SD,
        1,
        max
    ),
    .SDcols = bf_columns
]


############################################################
## 13. ADD COVARIATE NAMES
############################################################

BF_MERGED <- merge(
    BF_MERGED,
    COV_MAP,
    by = "COVARIABLE",
    all.x = TRUE,
    sort = FALSE
)


############################################################
## 14. ADD SNP METADATA
############################################################

META_BF <- copy(
    META
)

setnames(
    META_BF,
    "BayPass_row",
    "MRK"
)

BF_MERGED <- merge(
    BF_MERGED,
    META_BF,
    by = "MRK",
    all.x = TRUE,
    sort = FALSE
)


############################################################
## 15. FINAL XTX
##
## XtX was not combined across seeds.
## Seed 12345 is the representative converged run.
############################################################

XTX_FINAL <- merge(
    META,
    XTX[[REP_SEED]],
    by.x = "BayPass_row",
    by.y = "MRK",
    all.x = TRUE,
    sort = FALSE
)

if (anyNA(XTX_FINAL$M_XtX)) {
    stop(
        "Missing XtX values after metadata merge."
    )
}

setorder(
    XTX_FINAL,
    CHROM,
    POS
)

XTX_OUT <- XTX_FINAL[
    ,
    .(
        BayPass_row,
        CHROM,
        SNP,
        POS,
        REF,
        ALT,
        M_P,
        SD_P,
        M_XtX,
        SD_XtX,
        XtXst,
        log10_p = `log10(1/pval)`
    )
]

fwrite(
    XTX_OUT,
    file.path(
        OUTBASE,
        paste0(
            "XtX_seed",
            REP_SEED,
            ".tsv"
        )
    ),
    sep = "\t"
)


############################################################
## 16. FINAL C2
##
## C2 was not combined across seeds.
## Seed 12345 is the representative converged run.
############################################################

MP <- XTX_FINAL[
    ,
    .(
        BayPass_row,
        M_P
    )
]

C2_FINAL <- merge(
    META,
    C2[[REP_SEED]],
    by.x = "BayPass_row",
    by.y = "MRK",
    all.x = TRUE,
    sort = FALSE
)

C2_FINAL <- merge(
    C2_FINAL,
    MP,
    by = "BayPass_row",
    all.x = TRUE,
    sort = FALSE
)

if (
    anyNA(C2_FINAL$C2) ||
    anyNA(C2_FINAL$M_P)
) {
    stop(
        "Missing C2 or M_P after metadata merge."
    )
}

setorder(
    C2_FINAL,
    CHROM,
    POS
)

C2_OUT <- C2_FINAL[
    ,
    .(
        BayPass_row,
        CHROM,
        SNP,
        POS,
        REF,
        ALT,
        M_P,
        CONTRAST,
        C2,
        log10_p = `log10(1/pval)`
    )
]

fwrite(
    C2_OUT,
    file.path(
        OUTBASE,
        paste0(
            "C2_Host_seed",
            REP_SEED,
            ".tsv"
        )
    ),
    sep = "\t"
)


############################################################
## 17. ADD M_P TO FINAL GEA TABLE
############################################################

MP_BF <- copy(
    MP
)

setnames(
    MP_BF,
    "BayPass_row",
    "MRK"
)

BF_MERGED <- merge(
    BF_MERGED,
    MP_BF,
    by = "MRK",
    all.x = TRUE,
    sort = FALSE
)

setorder(
    BF_MERGED,
    COVARIABLE,
    CHROM,
    POS
)


GEA_OUT <- BF_MERGED[
    ,
    .(
        BayPass_row = MRK,
        CHROM,
        SNP,
        POS,
        REF,
        ALT,
        M_P,
        COVARIABLE,
        Covariate,
        BF_seed12345,
        BF_seed67890,
        BF_seed13579,
        BF_median,
        BF_min,
        BF_max
    )
]

fwrite(
    GEA_OUT,
    file.path(
        OUTBASE,
        "GEA_BF_median3seeds.tsv"
    ),
    sep = "\t"
)


############################################################
## 18. FINAL SUMMARY
############################################################

cat(
    "\n============================================================\n"
)

cat(
    "FINAL BAYPASS PREPARATION COMPLETE\n"
)

cat(
    "============================================================\n"
)

cat(
    "\nDataset:\n",
    "  all_snps\n"
)

cat(
    "\nRepresentative seed for XtX/C2:\n  ",
    REP_SEED,
    "\n"
)

cat(
    "\nGEA statistic:\n",
    "  median BF(dB) across seeds 12345, 67890, 13579\n"
)

cat(
    "\nFinal GEA covariates:\n"
)

print(
    COV_MAP
)

cat(
    "\nOmega FMD:\n"
)

print(
    OMEGA_FMD
)

cat(
    "\nBeta-prior estimates:\n"
)

print(
    BETA_TABLE
)

cat(
    "\nXtX correlations:\n"
)

print(
    XTX_COR
)

cat(
    "\nC2 correlations:\n"
)

print(
    C2_COR
)

cat(
    "\nGEA BF correlation summary:\n"
)

print(
    BF_COR_SUMMARY
)

cat(
    "\nOutputs:\n  ",
    OUTBASE,
    "\n"
)

cat(
    "\nDONE\n"
)
